export function favicon(domain){ return `https://www.google.com/s2/favicons?sz=64&domain=${domain}`; }

// Logo oficial do OpenStreetMap (a mesma arte usada no site deles —
// https://github.com/openstreetmap/openstreetmap-website/blob/master/app/assets/images/osm_logo.svg),
// embutida direto no app como base64. É só pra esse caso porque o ícone via
// Google Favicons (google.com/s2/favicons?...domain=openstreetmap.org) não
// estava carregando de forma confiável; embutir resolve de vez, sem
// depender de nenhum serviço externo nem de internet.
export const osmLogoDataUri = "data:image/svg+xml;base64,";
